    for (let i = 0; i < page.items.length; i++) {
      const val = page.items[i];
      if (val > 0 && val >= threshold) { kept.push(val); total += val; }
    }
    cursor = page.next;
  }
  host.store('summary', {pages, count: kept.length, total});
  return {pages, kept, total};
}

