  let hits = 0, misses = 0;
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    const cached = await host.readAsync('cache:' + k);
    if (cached !== null) {
      out[k] = cached;
      hits++;
    } else {
      const val = computeValue(k);
      host.store('cache:' + k, val);
      out[k] = val;
      misses++;
    }
  }
  return {out, hits, misses};
}

